-- findings where state = open | count by asset.environment, priority_class
Count of findings where state is open, grouped by asset.environment and priority_class, ordered by count descending

SELECT ((SELECT a.environment FROM assets a WHERE a.tenant_id = $1::uuid AND a.id = findings.asset_id))::text AS c0, (findings.priority_class)::text AS c1, count(*) AS c2 FROM findings WHERE findings.tenant_id = $2 AND ((findings.asset_id = ANY (ARRAY(SELECT uaa.asset_id FROM user_accessible_assets uaa WHERE uaa.user_id = $3 AND uaa.tenant_id = $4)) OR findings.assigned_to = $3) AND NOT EXISTS (SELECT 1 FROM assets ph WHERE ph.id = findings.asset_id AND ph.tenant_id = $4 AND ph.program_only AND EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND pp.visibility = 'private') AND NOT EXISTS (SELECT 1 FROM asset_program_links pl JOIN bounty_programs pp ON pp.tenant_id = pl.tenant_id AND pp.id = pl.program_id WHERE pl.tenant_id = ph.tenant_id AND pl.asset_id = ph.id AND NOT (pp.visibility = 'private' AND NOT EXISTS ( SELECT 1 FROM groups pg JOIN group_members pgm ON pgm.group_id = pg.id WHERE pg.tenant_id = pp.tenant_id AND pg.id = pp.group_id AND pg.is_active AND pgm.user_id = $3))))) AND (findings.source <> 'pentest' OR findings.pentest_campaign_id IN ( SELECT pcm.campaign_id FROM pentest_campaign_members pcm WHERE pcm.user_id = $5::uuid AND pcm.tenant_id = $2 AND (pcm.role <> 'client' OR findings.status NOT IN ('draft', 'in_review')))) AND ((findings.status IN ('confirmed', 'fix_applied', 'in_progress', 'new')) AND ((findings.status <> ALL($6::text[])) AND (findings.branch_only = $7::boolean) AND (NOT COALESCE((findings.asset_id IN (SELECT a.id FROM assets a WHERE a.tenant_id = $2 AND a.program_only)), FALSE)))) GROUP BY 1, 2 ORDER BY c2 DESC NULLS LAST, c0 ASC NULLS LAST, c1 ASC NULLS LAST LIMIT 1001

args: [11111111-1111-1111-1111-111111111111 11111111-1111-1111-1111-111111111111 22222222-2222-2222-2222-222222222222 11111111-1111-1111-1111-111111111111 22222222-2222-2222-2222-222222222222 {"draft","in_review"} false]
